CREATE TABLE public.organization_scopes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, organization_type text NOT NULL CHECK (organization_type IN ('empresa','ies')), name text NOT NULL, kind text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.organization_scopes TO authenticated; GRANT ALL ON public.organization_scopes TO service_role;
ALTER TABLE public.organization_scopes ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.organization_memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, organization_type text NOT NULL CHECK (organization_type IN ('empresa','ies')), user_id uuid NOT NULL, full_name text NOT NULL, email text NOT NULL, function_title text NOT NULL DEFAULT '', permissions text[] NOT NULL DEFAULT '{}', scope_ids uuid[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'ativo' CHECK (status IN ('ativo','suspenso','removido')), created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), last_access_at timestamptz, UNIQUE(organization_id,organization_type,user_id));
GRANT SELECT ON public.organization_memberships TO authenticated; GRANT ALL ON public.organization_memberships TO service_role;
ALTER TABLE public.organization_memberships ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.activity_logs ADD COLUMN organization_id uuid, ADD COLUMN organization_type text, ADD COLUMN entity text, ADD COLUMN scope_id uuid;
CREATE OR REPLACE FUNCTION public.organization_owner(_id uuid,_type text) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT owner_id FROM public.companies WHERE id=_id AND _type='empresa' UNION ALL SELECT owner_id FROM public.institutions WHERE id=_id AND _type='ies' $$;
CREATE OR REPLACE FUNCTION public.organization_permission(_id uuid,_type text,_permission text,_scope uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND public.current_profile_role()::text=_type AND (public.organization_owner(_id,_type)=auth.uid() OR EXISTS(SELECT 1 FROM public.organization_memberships m WHERE m.organization_id=_id AND m.organization_type=_type AND m.user_id=auth.uid() AND m.status='ativo' AND _permission=ANY(m.permissions) AND (cardinality(m.scope_ids)=0 OR (_scope IS NOT NULL AND _scope=ANY(m.scope_ids))))) $$;
CREATE OR REPLACE FUNCTION public.organization_member(_id uuid,_type text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND public.current_profile_role()::text=_type AND (public.organization_owner(_id,_type)=auth.uid() OR EXISTS(SELECT 1 FROM public.organization_memberships WHERE organization_id=_id AND organization_type=_type AND user_id=auth.uid() AND status='ativo')) $$;
CREATE POLICY scopes_read ON public.organization_scopes FOR SELECT TO authenticated USING(public.organization_member(organization_id,organization_type) AND (public.organization_owner(organization_id,organization_type)=auth.uid() OR EXISTS(SELECT 1 FROM public.organization_memberships m WHERE m.user_id=auth.uid() AND m.organization_id=organization_scopes.organization_id AND m.organization_type=organization_scopes.organization_type AND m.status='ativo' AND (cardinality(m.scope_ids)=0 OR organization_scopes.id=ANY(m.scope_ids)))));
CREATE POLICY memberships_read ON public.organization_memberships FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.organization_permission(organization_id,organization_type,'subperfis'));
CREATE POLICY organization_logs_read ON public.activity_logs FOR SELECT TO authenticated USING(public.organization_owner(organization_id,organization_type)=auth.uid() AND public.current_profile_role()::text=organization_type);
CREATE POLICY logs_personal_guard ON public.activity_logs AS RESTRICTIVE FOR ALL TO authenticated USING(organization_id IS NULL OR public.organization_owner(organization_id,organization_type)=auth.uid()) WITH CHECK(organization_id IS NULL);
CREATE OR REPLACE FUNCTION public.organization_access(_id uuid,_type text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.organization_memberships; owner boolean; BEGIN IF NOT public.organization_member(_id,_type) THEN RAISE EXCEPTION 'Acesso organizacional não autorizado'; END IF; owner:=public.organization_owner(_id,_type)=auth.uid(); SELECT * INTO m FROM public.organization_memberships WHERE organization_id=_id AND organization_type=_type AND user_id=auth.uid(); IF NOT owner THEN UPDATE public.organization_memberships SET last_access_at=now() WHERE id=m.id; END IF; RETURN jsonb_build_object('owner',owner,'permissions',CASE WHEN owner THEN ARRAY['colaboradores','competencias','cargos','vagas_internas','vagas_externas','candidatos','relatorios','faturamento','subperfis','conteudo','professores','cursos','validar_vinculos','bancarios'] ELSE m.permissions END,'scope_ids',CASE WHEN owner THEN '{}'::uuid[] ELSE m.scope_ids END); END $$;
CREATE OR REPLACE FUNCTION public.manage_organization_access(_id uuid,_type text,_action text,_payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target uuid; member public.organization_memberships; actor public.organization_memberships; perms text[]; scopes uuid[]; allowed text[]; owner boolean; result uuid; BEGIN IF NOT public.organization_member(_id,_type) THEN RAISE EXCEPTION 'Acesso negado'; END IF; owner:=public.organization_owner(_id,_type)=auth.uid(); SELECT * INTO actor FROM public.organization_memberships WHERE organization_id=_id AND organization_type=_type AND user_id=auth.uid() AND status='ativo'; IF NOT owner AND NOT ('subperfis'=ANY(actor.permissions)) THEN RAISE EXCEPTION 'Permissão de gestão necessária'; END IF;
IF _action='scope' THEN IF NOT owner THEN RAISE EXCEPTION 'Somente titular cadastra escopos'; END IF; IF length(trim(_payload->>'name'))<2 OR length(_payload->>'name')>120 THEN RAISE EXCEPTION 'Nome de escopo inválido'; END IF; INSERT INTO public.organization_scopes(organization_id,organization_type,name,kind) VALUES(_id,_type,trim(_payload->>'name'),COALESCE(_payload->>'kind','area')) RETURNING id INTO result;
ELSIF _action='transfer' THEN IF NOT owner THEN RAISE EXCEPTION 'Somente titular transfere a conta'; END IF; target:=(_payload->>'user_id')::uuid; SELECT * INTO member FROM public.organization_memberships WHERE organization_id=_id AND organization_type=_type AND user_id=target AND status='ativo'; IF NOT FOUND OR target=auth.uid() THEN RAISE EXCEPTION 'Selecione subperfil ativo'; END IF; IF _type='empresa' THEN UPDATE public.companies SET owner_id=target WHERE id=_id; ELSE UPDATE public.institutions SET owner_id=target WHERE id=_id; END IF; INSERT INTO public.organization_memberships(organization_id,organization_type,user_id,full_name,email,function_title,permissions,created_by) SELECT _id,_type,p.id,p.full_name,COALESCE(p.email,''),'Ex-titular',ARRAY['subperfis'],auth.uid() FROM public.profiles p WHERE p.id=auth.uid() ON CONFLICT(organization_id,organization_type,user_id) DO UPDATE SET status='ativo',permissions=ARRAY['subperfis']; result:=member.id;
ELSIF _action IN ('save','suspend','remove') THEN IF _action='save' THEN SELECT id INTO target FROM public.profiles WHERE lower(email)=lower(trim(_payload->>'email')); IF target IS NULL THEN RAISE EXCEPTION 'A pessoa deve criar sua conta antes de receber acesso'; END IF; ELSE SELECT user_id INTO target FROM public.organization_memberships WHERE id=(_payload->>'id')::uuid AND organization_id=_id AND organization_type=_type; END IF; IF target IS NULL OR target=public.organization_owner(_id,_type) THEN RAISE EXCEPTION 'Não é permitido alterar o titular'; END IF; SELECT * INTO member FROM public.organization_memberships WHERE organization_id=_id AND organization_type=_type AND user_id=target;
IF NOT owner AND member.id IS NOT NULL AND (NOT member.permissions <@ actor.permissions OR (cardinality(actor.scope_ids)>0 AND (cardinality(member.scope_ids)=0 OR NOT member.scope_ids <@ actor.scope_ids))) THEN RAISE EXCEPTION 'Subperfil fora do seu alcance de gestão'; END IF;
IF _action='save' THEN SELECT COALESCE(array_agg(value),'{}') INTO perms FROM jsonb_array_elements_text(COALESCE(_payload->'permissions','[]')); SELECT COALESCE(array_agg(value::uuid),'{}') INTO scopes FROM jsonb_array_elements_text(COALESCE(_payload->'scope_ids','[]')); allowed:=CASE WHEN _type='empresa' THEN ARRAY['colaboradores','competencias','cargos','vagas_internas','vagas_externas','candidatos','relatorios','faturamento','subperfis'] ELSE ARRAY['conteudo','professores','relatorios','cursos','validar_vinculos','bancarios','subperfis'] END; IF NOT perms <@ allowed THEN RAISE EXCEPTION 'Permissão inválida'; END IF; IF NOT owner AND (NOT perms <@ actor.permissions OR (cardinality(actor.scope_ids)>0 AND (cardinality(scopes)=0 OR NOT scopes <@ actor.scope_ids))) THEN RAISE EXCEPTION 'Não pode conceder acesso maior que o seu'; END IF; IF EXISTS(SELECT 1 FROM unnest(scopes) s WHERE NOT EXISTS(SELECT 1 FROM public.organization_scopes o WHERE o.id=s AND o.organization_id=_id AND o.organization_type=_type)) THEN RAISE EXCEPTION 'Escopo de outra organização'; END IF; IF length(trim(_payload->>'full_name'))<2 THEN RAISE EXCEPTION 'Informe o nome'; END IF;
INSERT INTO public.organization_memberships(organization_id,organization_type,user_id,full_name,email,function_title,permissions,scope_ids,status,created_by) VALUES(_id,_type,target,trim(_payload->>'full_name'),lower(trim(_payload->>'email')),COALESCE(_payload->>'function_title',''),perms,scopes,'ativo',auth.uid()) ON CONFLICT(organization_id,organization_type,user_id) DO UPDATE SET full_name=EXCLUDED.full_name,function_title=EXCLUDED.function_title,permissions=EXCLUDED.permissions,scope_ids=EXCLUDED.scope_ids,status='ativo' RETURNING id INTO result;
ELSE UPDATE public.organization_memberships SET status=CASE WHEN _action='suspend' THEN 'suspenso' ELSE 'removido' END WHERE organization_id=_id AND organization_type=_type AND user_id=target RETURNING id INTO result; END IF;
ELSE RAISE EXCEPTION 'Ação inválida'; END IF;
INSERT INTO public.activity_logs(user_id,action,organization_id,organization_type,entity,meta) VALUES(auth.uid(),'acesso_'||_action,_id,_type,'organization_memberships',jsonb_build_object('target_id',result)); RETURN result; END $$;
REVOKE ALL ON FUNCTION public.manage_organization_access(uuid,text,text,jsonb),public.organization_access(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.manage_organization_access(uuid,text,text,jsonb),public.organization_access(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.activate_organization(_id uuid,_type text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT (public.organization_owner(_id,_type)=auth.uid() OR EXISTS(SELECT 1 FROM public.organization_memberships WHERE organization_id=_id AND organization_type=_type AND user_id=auth.uid() AND status='ativo')) THEN RAISE EXCEPTION 'Acesso negado'; END IF; UPDATE public.profiles SET role=_type::public.profile_role,company_id=CASE WHEN _type='empresa' THEN _id ELSE NULL END,institution_id=CASE WHEN _type='ies' THEN _id ELSE NULL END,matching_enabled=false WHERE id=auth.uid(); END $$;
REVOKE ALL ON FUNCTION public.activate_organization(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.activate_organization(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.guard_profile_authority() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user IN ('authenticated','anon') THEN IF TG_OP='INSERT' AND (NEW.role IS NOT NULL OR NEW.company_id IS NOT NULL OR NEW.institution_id IS NOT NULL) THEN RAISE EXCEPTION 'Configure seu perfil pelo fluxo autorizado'; END IF; IF TG_OP='UPDATE' AND (NEW.role IS DISTINCT FROM OLD.role OR NEW.company_id IS DISTINCT FROM OLD.company_id OR NEW.institution_id IS DISTINCT FROM OLD.institution_id OR NEW.plan IS DISTINCT FROM OLD.plan) THEN RAISE EXCEPTION 'Alteração de perfil requer operação autorizada'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_profile_authority BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.guard_profile_authority();
CREATE POLICY learning_role_guard ON public.enrollments AS RESTRICTIVE FOR ALL TO authenticated USING(public.current_profile_role() IN ('estudante','geral','colaborador')) WITH CHECK(public.current_profile_role() IN ('estudante','geral','colaborador'));
CREATE POLICY certificate_role_guard ON public.certificates AS RESTRICTIVE FOR ALL TO authenticated USING(public.current_profile_role() IN ('estudante','geral','colaborador')) WITH CHECK(public.current_profile_role() IN ('estudante','geral','colaborador'));
CREATE POLICY preferences_role_guard ON public.employability_preferences AS RESTRICTIVE FOR ALL TO authenticated USING(public.current_profile_role() IN ('estudante','geral')) WITH CHECK(public.current_profile_role() IN ('estudante','geral'));
CREATE POLICY behavioral_role_guard ON public.behavioral_tests AS RESTRICTIVE FOR ALL TO authenticated USING(public.current_profile_role() IN ('estudante','geral','colaborador')) WITH CHECK(public.current_profile_role() IN ('estudante','geral','colaborador'));
ALTER TABLE public.jobs ADD COLUMN job_type text NOT NULL DEFAULT 'externa' CHECK(job_type IN ('interna','externa')), ADD COLUMN scope_id uuid REFERENCES public.organization_scopes(id);
CREATE POLICY job_visibility_guard ON public.jobs AS RESTRICTIVE FOR SELECT TO public USING((auth.uid() IS NULL AND job_type='externa') OR (public.current_profile_role() IN ('estudante','geral') AND job_type='externa') OR (public.current_profile_role()='colaborador' AND job_type='interna' AND company_id=(SELECT company_id FROM public.profiles WHERE id=auth.uid())) OR public.organization_permission(company_id,'empresa',CASE WHEN job_type='interna' THEN 'vagas_internas' ELSE 'vagas_externas' END,scope_id));
CREATE POLICY job_write_guard ON public.jobs AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(public.organization_permission(company_id,'empresa',CASE WHEN job_type='interna' THEN 'vagas_internas' ELSE 'vagas_externas' END,scope_id));
CREATE POLICY job_update_guard ON public.jobs AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.organization_permission(company_id,'empresa',CASE WHEN job_type='interna' THEN 'vagas_internas' ELSE 'vagas_externas' END,scope_id)) WITH CHECK(public.organization_permission(company_id,'empresa',CASE WHEN job_type='interna' THEN 'vagas_internas' ELSE 'vagas_externas' END,scope_id));
CREATE POLICY delegated_jobs_insert ON public.jobs FOR INSERT TO authenticated WITH CHECK(public.organization_permission(company_id,'empresa',CASE WHEN job_type='interna' THEN 'vagas_internas' ELSE 'vagas_externas' END,scope_id));
CREATE POLICY delegated_jobs_update ON public.jobs FOR UPDATE TO authenticated USING(public.organization_permission(company_id,'empresa',CASE WHEN job_type='interna' THEN 'vagas_internas' ELSE 'vagas_externas' END,scope_id));
ALTER TABLE public.matches ADD COLUMN profile_role public.profile_role NOT NULL DEFAULT 'estudante';
UPDATE public.matches m SET profile_role=p.role FROM public.profiles p WHERE p.id=m.user_id AND p.role IS NOT NULL;
CREATE TRIGGER matches_profile_role BEFORE INSERT ON public.matches FOR EACH ROW EXECUTE FUNCTION public.set_learning_profile_role();
CREATE POLICY match_role_guard ON public.matches AS RESTRICTIVE FOR ALL TO authenticated USING((user_id=auth.uid() AND profile_role=public.current_profile_role() AND public.current_profile_role() IN ('estudante','geral','colaborador')) OR (status='aceita' AND EXISTS(SELECT 1 FROM public.jobs j WHERE j.id=job_id AND public.organization_permission(j.company_id,'empresa','candidatos',j.scope_id)))) WITH CHECK(user_id=auth.uid() AND profile_role=public.current_profile_role() AND EXISTS(SELECT 1 FROM public.jobs j JOIN public.profiles p ON p.id=auth.uid() WHERE j.id=job_id AND ((p.role IN ('estudante','geral') AND j.job_type='externa' AND p.matching_enabled) OR (p.role='colaborador' AND j.job_type='interna' AND j.company_id=p.company_id))));
CREATE POLICY delegated_matches_read ON public.matches FOR SELECT TO authenticated USING(status='aceita' AND EXISTS(SELECT 1 FROM public.jobs j WHERE j.id=job_id AND public.organization_permission(j.company_id,'empresa','candidatos',j.scope_id)));
CREATE OR REPLACE FUNCTION public.accepted_candidate_profiles(_company uuid) RETURNS TABLE(match_id uuid,full_name text,email text,skills text[]) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT m.id,p.full_name,p.email,m.matched_skills FROM public.matches m JOIN public.jobs j ON j.id=m.job_id JOIN public.profiles p ON p.id=m.user_id WHERE j.company_id=_company AND m.status='aceita' AND public.organization_permission(j.company_id,'empresa','candidatos',j.scope_id) $$;
REVOKE ALL ON FUNCTION public.accepted_candidate_profiles(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.accepted_candidate_profiles(uuid) TO authenticated;